'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const S=require('./cleanup-schema.cjs'),B=require('./cleanup-backend.cjs'),F=require('./fixtures.cjs');const root=process.env.PUBLIC_TEST_TMP_ROOT;assert(root&&fs.existsSync(root));
function make(executed=false){const dir=fs.mkdtempSync(path.join(root,'known-name-pair-')),f=F.fixture(dir,{mode:'recover'}),active=f.jobMap.get(888);f.jobMap.set(889,{...active,id:889,name:'Recover positively unused KeyDB parity qualification / Retire positively unused KeyDB qualification '+S.slot(f.c.actor.target_locator),status:'completed',conclusion:executed?'failure':'skipped',runner_id:executed?999:0,runner_name:executed?active.runner_name:'',steps:executed?[{name:S.STEP,number:5,status:'completed',conclusion:'failure',started_at:'2026-10-24T15:01:01Z',completed_at:'2026-10-24T15:01:02Z'}]:[]});return f;}
test('actual known reader keeps skipped unused native row without duplicate exact actor ambiguity',async()=>{const f=make(),b=await B.readTarget(f.c,f.deps),h=await B.handlerHistory(f.c,b,[],f.deps);assert.equal(h.handlers.length,2);assert(h.handlers.some(x=>x.job_id===889&&!x.executed));assert.deepEqual(h.wire_clear,{close:true,remove:true});});
test('known history retains executed unused handler missing-record veto',async()=>{const f=make(true),b=await B.readTarget(f.c,f.deps);await assert.rejects(B.handlerHistory(f.c,b,[],f.deps));});
